    out, cur = [], ""
    for b in blocks:
        head = b.split("\n", 1)[0] + "\n" if b.startswith("=== PAGE") else ""
        parts = b.split(PAGE_BREAK)
        pieces = []
        for i, part in enumerate(parts):
            part = part if i == 0 else head + part
            pieces += [part[j:j + size] for j in range(0, len(part), size)] or [""]
        for piece in pieces:
            if cur and len(cur) + len(piece) > size:
                out.append(cur)
                cur = ""
            cur += piece + "\n\n"
    if cur.strip():
        out.append(cur)
    return out


async def extract(ctx, instruction: str, shape: str, blocks: list[str], *, list_key: str | tuple | None = None,
                  context: str = "", chunk_size: int = CHUNK) -> dict:
    """Ask the model to extract `shape` from the blocks. With `list_key` (one key or several), chunks are processed in
    parallel and the lists under those keys are concatenated (for long paged lists); otherwise one call."""
    keys = (list_key,) if isinstance(list_key, str) else tuple(list_key or ())
    if not blocks:
        return {k: [] for k in keys}
    user_head = f"{instruction}\n\nJSON shape:\n{shape}\n" + (f"\nContext:\n{context}\n" if context else "")
    if not keys:
        out = await ctx.llm.ask_json(SYSTEM, user_head + "\nPAGES:\n" + "\n\n".join(blocks)[:4 * CHUNK])
        return out if isinstance(out, dict) else {}
    parts = chunks(blocks, chunk_size)
    replies = await asyncio.gather(*(ctx.llm.ask_json(SYSTEM, user_head + "\nPAGES:\n" + p) for p in parts),
                                   return_exceptions=True)
    merged: dict = {k: [] for k in keys}
    for r in replies:
        if isinstance(r, Exception):
            log.warning("extract chunk failed: %s", r)
            continue
        if isinstance(r, list) and len(keys) == 1:
            merged[keys[0]] += r
        elif isinstance(r, dict):
            for k, v in r.items():
                if k in keys:
                    merged[k] += v if isinstance(v, list) else []
                elif v not in (None, "", [], {}):
                    merged.setdefault(k, v)
    return merged


def brief_section(brief: str, *names: str) -> str:
    """The text of markdown sections whose heading contains one of `names` (case-insensitive)."""
    out, keep = [], False
    for line in brief.splitlines():
        if line.startswith("#"):
            keep = any(n.lower() in line.lower() for n in names)
        if keep:
            out.append(line)
    return "\n".join(out).strip()


def brief_intro(brief: str, limit: int = 1500) -> str:
    """The brief up to its first second-level section: who we are and what the tender is."""
    head = re.split(r"\n##\s", brief, maxsplit=1)[0]
    return head.strip()[:limit]
"""Model access for agents: concurrency-limited, usage-counted, JSON-friendly. Qwen by default (hosted, free)."""
import asyncio
import json
import re

import models


def parse_json(text: str):
    """The first JSON object/array in a model reply (tolerates ``` fences and chatter)."""
    text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.M).strip()
    for opener, closer in (("{", "}"), ("[", "]")):
        start, end = text.find(opener), text.rfind(closer)
        if start != -1 and end > start:
            try:
                return json.loads(text[start:end + 1])
            except ValueError:
                continue
    raise ValueError(f"no JSON in model reply: {text[:200]}")


class LLM:
    def __init__(self, max_concurrent: int = 24):
        self._sem = asyncio.Semaphore(max_concurrent)   # team limit is 32 concurrent Qwen calls
        self._client = None
        self.calls = 0
        self.tokens = {"prompt": 0, "completion": 0}

    @property
    def client(self):
        self._client = self._client or models.qwen()
        return self._client

    async def chat(self, messages: list[dict], *, tools: list[dict] | None = None, model: str = models.QWEN_MODEL,
                   think: bool = False, **kwargs):
        """One chat completion; returns the message (`.content`, `.tool_calls`). `think=True` lets Qwen run its
        separate reasoning pass (slower, more tokens): use it for judgement calls, not for plain extraction."""
        args = dict(model=model, messages=messages, **kwargs)
        args.setdefault("temperature", 0)
        if not think and model == models.QWEN_MODEL:
            args["extra_body"] = {**(args.get("extra_body") or {}), **models.NO_THINKING}
        if tools:
            args["tools"] = tools
        async with self._sem:
            reply = await self.client.chat.completions.create(**args)
        self.calls += 1
        if reply.usage:
            self.tokens["prompt"] += reply.usage.prompt_tokens or 0
            self.tokens["completion"] += reply.usage.completion_tokens or 0
        return reply.choices[0].message

    async def ask(self, system: str, user: str, **kwargs) -> str:
        message = await self.chat([{"role": "system", "content": system}, {"role": "user", "content": user}], **kwargs)
        return message.content or ""

    async def ask_json(self, system: str, user: str, retries: int = 1, **kwargs):
        """Ask for JSON; re-ask once with the parse error if the reply is not valid."""
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        kwargs.setdefault("response_format", {"type": "json_object"})    # Qwen then always answers with JSON
        for _ in range(retries + 1):
            reply = (await self.chat(messages, **kwargs)).content or ""
            try:
                return parse_json(reply)
            except ValueError as error:
                messages += [{"role": "assistant", "content": reply},
                             {"role": "user", "content": f"Invalid: {error}. Reply with valid JSON only."}]
        raise ValueError("model did not return valid JSON")
"""Which website plays which role. Site ids and names differ between datasets, so the model maps them from the brief
once per run; the result is cached on the board as results["sites"] = {role: siteId}."""
import logging

log = logging.getLogger("sites")

ROLES = {
    "tender": "public procurement / tender portal: the tender, its bill of quantities, bidder Q&A, bid submission",
    "spec": "the buyer's supplier/customer portal holding the technical specification (Lastenheft) and its revisions",
    "erp": "our own ERP: materials, stock, lead times, price conditions",
    "mail": "our webmail / sales inbox: approvals, internal release mails, signing TANs",
}


async def resolve_roles(ctx) -> dict:
    """{role: siteId} for the four roles; asks the model once, validates against the task's site ids."""
    async with ctx.lock("sites"):
        known = ctx.board.get("sites")
        if known:
            return known
        sites = [{"siteId": s.get("siteId"), "url": s.get("url")} for s in ctx.task.get("access", [])]
        mapping = {}
        if len(sites) > 1:
            try:
                out = await ctx.llm.ask_json(
                    "Map each role to exactly one siteId. Reply JSON {role: siteId}.",
                    f"Roles: {ROLES}\nSites: {sites}\nBrief (start):\n{ctx.brief[:2500]}")
                mapping = {r: v for r, v in (out or {}).items() if r in ROLES and v in ctx.site_ids}
            except Exception as error:   # fall through to the single-site / partial mapping below
                log.warning("role mapping failed: %s", error)
        for role in ROLES:                # any role the model left open: a site whose id or URL names it
            if role not in mapping:
                for s in sites:
                    if role in f"{s['siteId']} {s['url']}".lower() and s["siteId"] not in mapping.values():
                        mapping[role] = s["siteId"]
                        break
        await ctx.board.set("sites", mapping)
        log.info("site roles: %s", mapping)
        return mapping


async def site_for(ctx, role: str) -> str:
    mapping = await resolve_roles(ctx)
    if role not in mapping:
        raise KeyError(f"no website found for role {role!r}: {mapping}")
    return mapping[role]
"""Page extraction helpers: turn the page a model has opened into plain text it (and the analysts) can read.

Business sites hide facts in places a screenshot or the visible text misses: collapsed <details>, hover tooltips,
canvas images with an aria-label, same-origin iframes, zero-width characters inside numbers and references. The
extractor reads all of those, and skips content that is explicitly hidden from people (`hidden`, `aria-hidden`,
closed dialogs, scripts and styles), because that content is not part of the page a person sees.
"""
import re

# Runs in the page: (opts) => text. Recurses into same-origin iframes. Kept dependency-free and short.
EXTRACT_JS = r"""(opts) => {
  const SKIP = new Set(['SCRIPT','STYLE','NOSCRIPT','TEMPLATE','SVG','HEAD','META','LINK']);
  const BLOCK = /^(P|DIV|SECTION|ARTICLE|MAIN|ASIDE|HEADER|FOOTER|NAV|UL|OL|LI|TABLE|THEAD|TBODY|TR|H[1-6]|DL|DT|DD|FORM|FIELDSET|LEGEND|DETAILS|SUMMARY|PRE|BLOCKQUOTE|CAPTION|LABEL|FIGURE|BR|HR)$/;
  const out = [];
  const push = s => { if (s) out.push(s); };
  const hiddenForPeople = el => el.hasAttribute('hidden') || el.getAttribute('aria-hidden') === 'true'
    || (el.tagName === 'DIALOG' && !el.open)
    || (el.style && el.style.display === 'none' && el.getAttribute('role') !== 'tooltip');
  const walk = (node, depth) => {
    if (node.nodeType === 3) { push(node.nodeValue); return; }
    if (node.nodeType !== 1) return;
    const el = node, tag = el.tagName;
    if (SKIP.has(tag) || hiddenForPeople(el)) return;
    const role = el.getAttribute('role'), label = el.getAttribute('aria-label');
    if (tag === 'IFRAME') {
      let doc = null; try { doc = el.contentDocument; } catch (e) {}
      const src = el.getAttribute('src') || '';
      push(`\n[iframe ${el.getAttribute('title') || src}]\n`);
      if ((!doc || !doc.body || !doc.body.innerText.trim()) && el.getAttribute('srcdoc')) {
        doc = new DOMParser().parseFromString(el.getAttribute('srcdoc'), 'text/html');   // inline frame content
      }
      if (doc && doc.body && doc.body.innerText.trim() && depth < 4) walk(doc.body, depth + 1);
      else push(`(frame not loaded or not readable${src ? '; open it directly with read_page(url="' + src + '")' : ''})`);
      push('\n[/iframe]\n'); return;
    }
    if (tag === 'CANVAS' || (role === 'img' && label)) { push(` ${label || el.textContent || ''} `); return; }
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') {
      const t = (el.type || '').toLowerCase();
      if (t === 'hidden' || t === 'password') return;
      let v = tag === 'SELECT' ? (el.selectedOptions[0] ? el.selectedOptions[0].text : '') : el.value;
      if (t === 'checkbox' || t === 'radio') v = el.checked ? '[x]' : '[ ]';
      push(` [${el.name || label || t || 'field'}: ${v}] `); return;
    }
    if (tag === 'TIME' && el.getAttribute('datetime')) push(` [${el.getAttribute('datetime')}] `);
    if (role === 'tooltip') push(' (tooltip: ');
    if (tag === 'TD' || tag === 'TH') push(' | ');
    if (BLOCK.test(tag)) push('\n');
    if (tag === 'SUMMARY') push('▸ ');
    for (const child of el.childNodes) walk(child, depth);
    if (role === 'tooltip') push(') ');
    if (BLOCK.test(tag)) push('\n');
  };
  walk(document.body, 0);
  return out.join('');
}"""

# Runs in the page: (label) => "clicked" | "missing". Clicks the first link/button whose text matches `label`
# (the model names it), in the top document or a same-origin iframe, so a paged result set can be followed.
NEXT_JS = r"""(label) => {
  const norm = s => (s || '').replace(/[​-‍⁠﻿]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
  const want = norm(label);
  const docs = [document];
  for (let i = 0; i < docs.length && i < 20; i++) {
    for (const f of docs[i].querySelectorAll('iframe')) { try { if (f.contentDocument) docs.push(f.contentDocument); } catch (e) {} }
  }
  for (const doc of docs) {
    for (const el of doc.querySelectorAll('a[href], button')) {
      if (el.disabled || el.closest('[hidden],[aria-hidden=true]')) continue;
      if (norm(el.textContent) === want || norm(el.getAttribute('aria-label')) === want) { el.click(); return 'clicked'; }
    }
  }
  return 'missing';
}"""

_ZERO_WIDTH = re.compile(r"[​-‍⁠﻿­]")


def clean(text: str) -> str:
    """Remove zero-width characters and collapse blank space, keeping line structure."""
    text = _ZERO_WIDTH.sub("", text or "")
    lines = [re.sub(r"[ \t ]+", " ", line).strip() for line in text.splitlines()]
    out, blank = [], False
    for line in lines:
        if line in ("", "|"):
            if not blank and out:
                out.append("")
            blank = True
            continue
        out.append(line.strip(" |") if line.count("|") == 1 else line)
        blank = False
    return "\n".join(out).strip()

# OWNER: (name)   ROLE: analyst   NEEDS: mail.page (done.mail_core / done.mail), results["brief"]
# WRITES: results["discount"], results["mail"], results["mail_messages"]
"""Turns the saved mails into records, then applies the authority rules in code: only the sender the brief authorises
for a topic (local part + our mailbox domain), only the EXACT tender reference, only records dated no later than the
scenario date, newest record per key wins, drafts/previews never count.

results["discount"] = {"percent": "5", "min_order_value": "1.00" | None, "source": subject/date} (percent "0" if none)
results["mail"] = {
  "condition_rules": {key: "base_only" | "base_and_surcharge" | "none"},
  "technical_release": {key: {"revision", "reserve_mm_per_end"}},
  "packaging_tariffs": {key: eur_per_carton}, "delivery_commitments": {key: {"material", "weeks", "max_total_pieces"}},
  "setup_pools": {key: eur_fee}, "project_bonus": {key: [{"from", "to", "percent"}]},
  "fx_fixing": {currency: eur_per_unit}, "price_indices": {index: eur_per_kg}
}  (numbers as strings)
"""
import asyncio
from datetime import datetime

from swarm import Agent, Phase, register
from swarm.extract import extract, page_block, pages
from swarm.normalize import norm_ref, to_datetime, to_decimal

EPOCH = to_datetime("1970-01-01T00:00:00Z")

TOPICS = ["discount_approval", "condition_rules", "technical_release", "packaging_tariffs", "delivery_commitments",
          "setup_pools", "project_bonus", "fx_fixing", "price_indices", "signing_tan", "other"]

SHAPE = """{"mailbox_owner": "our mailbox address (logged-in user / recipient) if shown",
 "messages": [{"subject": "", "sender": "full sender address", "date": "UTC ISO timestamp", "folder": "",
  "reference": "tender reference exactly as in message (keep suffixes)",
  "topic": "one of: """ + ", ".join(TOPICS) + """",
  "is_draft": "true only if this message itself is unsent draft/local preview",
  "valid_from_message_date": "true if message says it applies only from its own date on",
  "discount_percent": null, "min_order_value_eur": null,
  "entries": [{"key": "key/code as written", "revision": null, "reserve_mm_per_end": null, "eur_per_carton": null,
     "material": null, "weeks": null, "max_total_pieces": null, "pool_fee_eur": null,
     "bands": [{"from_eur": 0, "to_eur": null, "percent": 0}], "currency": null, "eur_per_currency_unit": null,
     "discount_scope": "for condition rules: base_only | base_and_surcharge | none", "index": null,
     "eur_per_kg": null, "valid_from": null, "valid_to": null}]}]}"""

INSTRUCTION = ("Extract every mail MESSAGE on these pages (ignore result lists without message text). Values from "
               "original message text, NOT from local preview/unsent draft section. Numbers -> JSON numbers using the "
               "number format the message states (e.g. decimal point). Condition rules: decide per key from prose "
               "whether order discount applies to base price only, to base price + weight-based material surcharge, "
               "or to nothing.")


def _local(addr) -> str:
    return str(addr or "").strip().lower().split("@")[0]


def _domain(addr) -> str:
    return str(addr or "").strip().lower().rpartition("@")[2]


def valid_messages(messages: list[dict], ref: str, scenario: datetime | None, senders: dict, domain: str) -> list[dict]:
    out = []
    for m in messages:
        if m.get("is_draft") in (True, "true") or norm_ref(m.get("reference")) != norm_ref(ref):
            continue
        want = _local(senders.get(m.get("topic"), ""))
        if want and _local(m.get("sender")) != want:
            continue
        if domain and _domain(m.get("sender")) and _domain(m.get("sender")) != domain:
            continue
        date = to_datetime(m.get("date"))
        if scenario and date and date > scenario:
            continue
        out.append(m)
    return sorted(out, key=lambda m: to_datetime(m.get("date")) or EPOCH)


def latest_entries(messages: list[dict], topic: str) -> dict:
    """{key: entry} from the newest valid message per key (messages sorted oldest first)."""
    out = {}
    for m in messages:
        if m.get("topic") == topic:
            for e in m.get("entries") or []:
                if e.get("key") or e.get("index") or e.get("currency"):
                    out[norm_ref(e.get("key") or e.get("index") or e.get("currency"))] = e | {"_date": m.get("date")}
    return out


def summarise(messages: list[dict], scenario: datetime | None) -> dict:
    s = lambda v: None if v in (None, "") else format(to_decimal(v).normalize(), "f") if to_decimal(v) is not None else None  # noqa: E731
    mail = {"condition_rules": {k: e.get("discount_scope") for k, e in latest_entries(messages, "condition_rules").items()},
            "technical_release": {k: {"revision": e.get("revision"), "reserve_mm_per_end": s(e.get("reserve_mm_per_end"))}
                                  for k, e in latest_entries(messages, "technical_release").items()},
            "packaging_tariffs": {k: s(e.get("eur_per_carton")) for k, e in latest_entries(messages, "packaging_tariffs").items()},
            "delivery_commitments": {k: {"material": e.get("material"), "weeks": s(e.get("weeks")),
                                         "max_total_pieces": s(e.get("max_total_pieces"))}
                                     for k, e in latest_entries(messages, "delivery_commitments").items()},
            "setup_pools": {k: s(e.get("pool_fee_eur")) for k, e in latest_entries(messages, "setup_pools").items()},
            "project_bonus": {k: [{"from": s(b.get("from_eur")) or "0", "to": s(b.get("to_eur")), "percent": s(b.get("percent"))}
                                  for b in e.get("bands") or []]
                              for k, e in latest_entries(messages, "project_bonus").items()},
            "fx_fixing": {}, "price_indices": {}}
    for m in messages:                                   # newest message last, so it wins
        for e in m.get("entries") or []:
            if m.get("topic") == "fx_fixing" and e.get("currency"):
                mail["fx_fixing"][norm_ref(e["currency"])] = s(e.get("eur_per_currency_unit"))
            if m.get("topic") == "price_indices" and e.get("index"):
                start, end = to_datetime(e.get("valid_from")), to_datetime(e.get("valid_to"))
                if end and end.hour == 0 and end.minute == 0:
                    end = end.replace(hour=23, minute=59, second=59)
                inside = scenario is None or ((start is None or start <= scenario) and (end is None or scenario <= end))
                if inside:
                    mail["price_indices"][norm_ref(e["index"])] = s(e.get("eur_per_kg"))
    return mail


@register
class DiscountAnalyzer(Agent):
    phase = Phase.COLLECT

    async def extract_new(self, cache: dict) -> None:
        todo = [e for e in pages(self.ctx, "mail") if (e.data.get("url"), hash(e.data.get("text", ""))) not in cache]
        replies = await asyncio.gather(*(extract(self.ctx, INSTRUCTION, SHAPE, [page_block(e)]) for e in todo),
                                       return_exceptions=True)
        for e, r in zip(todo, replies):
            cache[(e.data.get("url"), hash(e.data.get("text", "")))] = r if isinstance(r, dict) else {}

    async def publish(self, cache: dict) -> None:
        facts = self.ctx.board.get("brief") or {}
        ref, scenario = facts.get("tender_reference", ""), to_datetime(facts.get("scenario_date"))
        senders = {k: v for k, v in (facts.get("authorized_senders") or {}).items() if v}
        if facts.get("director_sender"):
            senders.setdefault("discount_approval", facts["director_sender"])
        owners = [r.get("mailbox_owner") for r in cache.values() if r.get("mailbox_owner")]
        domain = _domain(owners[0]) if owners else ""
        messages = [m for r in cache.values() for m in (r.get("messages") or [])]
        unique = {(m.get("subject"), m.get("date"), m.get("sender")): m for m in messages}
        valid = valid_messages(list(unique.values()), ref, scenario, senders, domain)
        approvals = [m for m in valid if m.get("topic") == "discount_approval" and m.get("discount_percent") is not None]
        if approvals:
            a = approvals[-1]
            discount = {"percent": format(to_decimal(a["discount_percent"]).normalize(), "f"),
                        "min_order_value": (format(to_decimal(a["min_order_value_eur"]).normalize(), "f")
                                            if a.get("min_order_value_eur") not in (None, "") else None),
                        "source": f"{a.get('subject')} {a.get('date')} {a.get('sender')}"}
        else:
            discount = {"percent": "0", "min_order_value": None, "source": "no valid approval found"}
        await self.ctx.board.set("mail_messages", list(unique.values()))
        if owners:
            await self.ctx.board.set("mailbox", owners[0])
        await self.ctx.board.set("discount", discount)
        await self.ctx.board.set("mail", summarise(valid, scenario))
        self.log.info("discount %s; %d/%d valid messages", discount, len(valid), len(unique))

    async def run(self) -> None:
        cache: dict = {}
        await self.ctx.board.wait_for(key="done.mail_core", timeout=max(1.0, self.ctx.time_left()))
        await self.extract_new(cache)
        await self.publish(cache)
        await self.ctx.board.wait_for(key="done.mail", timeout=max(1.0, self.ctx.time_left()))
        await self.extract_new(cache)
        await self.publish(cache)
        await self.ctx.board.set("mail_final", True)
# OWNER: (name)   ROLE: calculator (plain code, no model)
# NEEDS: brief, tender, quantities, requirements, materials, erp, discount, mail   WRITES: results["bid"], results["answer"]
"""Deterministic pricing, lead times and allocations per the brief's rules. Every input that is missing only removes
the fields that depend on it: a position without material/price is omitted, an unknown surcharge leaves the
surcharge field blank, and so on (a signed partial bid beats nothing).

results["bid"] = {"answer": <answer schema dict>, "omitted": [positions], "lines": [{position, display strings,
                  material attributes for the configurator, notes}], "issues": [str]}
results["answer"] = results["bid"]["answer"]
"""
import math
from decimal import ROUND_FLOOR, Decimal

from agents.analyze_quantities import withdrawn_numbers
from swarm import Agent, Phase, register
from swarm.normalize import de_number, norm_ref, round_cents, to_datetime, to_decimal

D0 = Decimal(0)


def is_set_unit(unit) -> bool:
    u = str(unit or "").strip().lower()
    return u.startswith("satz") or u.startswith("set") or u.startswith("sätze")


def valid_condition(conditions: list[dict], material: str, scenario) -> dict | None:
    """The material's price condition valid on the scenario date (both endpoints inclusive); latest start wins."""
    valid = []
    for c in conditions:
        if norm_ref(c.get("material")) != norm_ref(material):
            continue
        start, end = to_datetime(c.get("valid_from")), to_datetime(c.get("valid_to"))
        if end and end.hour == 0 and end.minute == 0 and end.second == 0:
            end = end.replace(hour=23, minute=59, second=59)
        if scenario is None or ((start is None or start <= scenario) and (end is None or scenario <= end)):
            valid.append((start or to_datetime("1970-01-01"), c))
    return max(valid, key=lambda x: x[0])[1] if valid else None


def scale_price(condition: dict, pieces: int) -> Decimal | None:
    """Per-piece price at the highest scale whose minimum quantity <= pieces, divided by the price unit."""
    fmt = condition.get("number_format")
    rows = []
    for s in condition.get("scales") or []:
        q, p = to_decimal(s.get("min_qty"), fmt), to_decimal(s.get("price"), fmt)
        if q is not None and p is not None and q <= pieces:
            rows.append((q, p))
    if not rows:
        return None
    unit = to_decimal(condition.get("price_unit")) or Decimal(1)
    return max(rows)[1] / (unit if unit > 0 else Decimal(1))


def allocate_cents(total: Decimal, weights: dict[str, Decimal]) -> dict[str, Decimal]:
    """Split `total` (EUR) proportionally in cents: floor, then remaining cents to the largest remainders,
    ties by ascending position identifier."""
    cents = int((total * 100).to_integral_value())
    wsum = sum(weights.values(), D0)
    if wsum <= 0 or not weights:
        return {k: D0 for k in weights}
    exact = {k: Decimal(cents) * w / wsum for k, w in weights.items()}
    floors = {k: int(v.to_integral_value(rounding=ROUND_FLOOR)) for k, v in exact.items()}
    rest = cents - sum(floors.values())
    order = sorted(weights, key=lambda k: (-(exact[k] - floors[k]), k))
    for k in order[:rest]:
        floors[k] += 1
    return {k: Decimal(v) / 100 for k, v in floors.items()}


def marginal_bonus(base_total: Decimal, bands: list[dict]) -> Decimal:
    credit = D0
    for b in bands:
        lo = to_decimal(b.get("from")) or D0
        hi = to_decimal(b.get("to")) if b.get("to") not in (None, "", "null") else None
        pct = to_decimal(b.get("percent")) or D0
        top = base_total if hi is None else min(base_total, hi)
        if top > lo:
            credit += (top - lo) * pct / 100
    return round_cents(credit)


def position_keys(clarifications: list[dict], position: str) -> dict:
    """Commercial keys and setup fee the latest Q&A answers assign to a position (withdrawn answers ignored)."""
    withdrawn = withdrawn_numbers(clarifications)
    keys, fee = {}, None
    ordered = sorted(clarifications, key=lambda c: to_datetime(c.get("date")) or to_datetime("1970-01-01"))
    for c in ordered:
        if norm_ref(c.get("number")) in withdrawn or position not in [str(x).strip() for x in c.get("positions") or []]:
            continue
        for k, v in (c.get("keys") or {}).items():
            if v not in (None, "", "null"):
                keys[k] = v
        if c.get("setup_fee") not in (None, "", "null"):
            fee = to_decimal(c["setup_fee"], "de-DE" if "," in str(c["setup_fee"]) else None)
    return {"keys": keys, "setup_fee": fee}


def compute(inputs: dict) -> dict:
    brief, tender = inputs.get("brief") or {}, inputs.get("tender") or {}
    quantities, requirements = inputs.get("quantities") or {}, inputs.get("requirements") or {}
    matched, erp = inputs.get("materials") or {}, inputs.get("erp") or {}
    discount, mail = inputs.get("discount") or {}, inputs.get("mail") or {}
    scenario = to_datetime(brief.get("scenario_date"))
    erp_materials = {norm_ref(k): v for k, v in (erp.get("materials") or {}).items()}
    issues, omitted, lines = [], [], {}
    clarifications = tender.get("clarifications") or []

    # 1. per position: pieces, material, EUR base price
    for p in tender.get("positions") or []:
        pos = str(p.get("position")).strip()
        q = (quantities.get(pos) or {}).get("quantity")
        req = next((v for k, v in requirements.items() if norm_ref(k) == norm_ref(p.get("requirement_ref"))), {}) or {}
        mat = (matched.get(pos) or {}).get("material")
        line = {"position": pos, "material": mat, "unit": p.get("unit"), "required": (matched.get(pos) or {}).get("required"),
                "short_text": p.get("short_text"), **position_keys(clarifications, pos)}
        lines[pos] = line
        if q is None:
            issues.append(f"{pos}: no quantity")
            continue
        if is_set_unit(p.get("unit")):
            per_set = to_decimal(req.get("pieces_per_set"))
            if not per_set:
                issues.append(f"{pos}: quantity in sets but pieces per set unknown")
                continue
            q = int(Decimal(q) * per_set)
        line["pieces"] = int(q)
        if not mat:
            issues.append(f"{pos}: no material ({(matched.get(pos) or {}).get('reason')})")
            continue
        cond = valid_condition(erp.get("conditions") or [], mat, scenario)
        price = scale_price(cond, int(q)) if cond else None
        if price is None:
            issues.append(f"{pos}: no valid price condition/scale for {mat}")
            continue
        currency = norm_ref((cond or {}).get("currency") or "EUR")
        if currency != "EUR":
            rate = to_decimal((mail.get("fx_fixing") or {}).get(currency))
            if rate is None:
                issues.append(f"{pos}: price in {currency}, no FX rate")
                continue
            price = price * rate
        line["base"] = round_cents(price)
        line["erp"] = erp_materials.get(norm_ref(mat), {})
        # the configurator lists the catalogue's own attribute values, so the submitter selects these
        line["configuration"] = {k: line["erp"].get(k) for k in ("bore", "stroke", "pressure", "mounting", "certification")}

    priced = {pos: l for pos, l in lines.items() if "base" in l}
    omitted = [pos for pos in lines if pos not in priced]

    # 2. order-level discount (threshold on undiscounted goods value of all priced positions)
    pct = to_decimal(discount.get("percent")) or D0
    threshold = to_decimal(discount.get("min_order_value"))
    order_value = round_cents(sum((l["pieces"] * l["base"] for l in priced.values()), D0))
    if threshold is not None and order_value < threshold:
        pct = D0
    d = pct / 100

    # 3. shared setup pools, project bonus (allocations in cents)
    pools: dict[str, dict] = {}
    bonus: dict[str, dict] = {}
    for pos, l in priced.items():
        if l["keys"].get("setup_pool"):
            pools.setdefault(norm_ref(l["keys"]["setup_pool"]), {})[pos] = l
        if l["keys"].get("bonus_plan"):
            bonus.setdefault(norm_ref(l["keys"]["bonus_plan"]), {})[pos] = l
    for key, members in pools.items():
        fee = to_decimal((mail.get("setup_pools") or {}).get(key))
        weights = {pos: Decimal(l["pieces"]) * (to_decimal(l["erp"].get("allocation_mass_g")) or D0) for pos, l in members.items()}
        if fee is None or not any(weights.values()):
            for l in members.values():
                l["pool_unknown"] = True
            continue
        for pos, amount in allocate_cents(fee, weights).items():
            members[pos]["pool"] = amount
    for key, members in bonus.items():
        bands = (mail.get("project_bonus") or {}).get(key)
        if not bands:
            for l in members.values():
                l["bonus_unknown"] = True
            continue
        values = {pos: l["pieces"] * l["base"] for pos, l in members.items()}
        credit = marginal_bonus(sum(values.values(), D0), bands)
        for pos, amount in allocate_cents(credit, values).items():
            members[pos]["bonus"] = amount

    # 4. per-position surcharge, packaging, final price
    for pos, l in priced.items():
        n = Decimal(l["pieces"])
        rate = to_decimal((mail.get("price_indices") or {}).get(norm_ref(l["erp"].get("metal_index"))))
        mass = to_decimal(l["erp"].get("surcharge_mass_g"))
        l["mass_surcharge"] = mass / 1000 * rate if (rate is not None and mass is not None) else None
        tariff_key = l["keys"].get("packaging_tariff")
        tariff = to_decimal((mail.get("packaging_tariffs") or {}).get(norm_ref(tariff_key))) if tariff_key else D0
        carton = to_decimal(l["erp"].get("pieces_per_carton"))
        if tariff_key and (tariff is None or not carton):
            l["packaging_total"] = None
        else:
            l["packaging_total"] = (tariff * math.ceil(n / carton)) if tariff_key else D0
        scope = (mail.get("condition_rules") or {}).get(norm_ref(l["keys"].get("konditionsgruppe"))) \
            if l["keys"].get("konditionsgruppe") else "base_only"
        scope = scope or "base_only"
        base_factor = (1 - d) if scope in ("base_only", "base_and_surcharge") else Decimal(1)
        sur_factor = (1 - d) if scope == "base_and_surcharge" else Decimal(1)
        setup = (l.get("setup_fee") or D0) + l.get("pool", D0)
        extras = setup + (l["packaging_total"] or D0) - l.get("bonus", D0)
        final = l["base"] * base_factor + (l["mass_surcharge"] or D0) * sur_factor + extras / n
        l["unit_price"] = round_cents(final)
        l["surcharge_report"] = (round_cents(l["mass_surcharge"] + setup / n)
                                 if l["mass_surcharge"] is not None and not l.get("pool_unknown") else None)
        l["packaging_report"] = round_cents(l["packaging_total"] / n) if l["packaging_total"] is not None else None
        l["rebate_report"] = None if l.get("bonus_unknown") else round_cents(l.get("bonus", D0))

    # 5. lead times: delivery commitment, else shared stock all-or-nothing per material
    demand: dict[str, int] = {}
    for l in priced.values():
        demand[norm_ref(l["material"])] = demand.get(norm_ref(l["material"]), 0) + l["pieces"]
    stock = {norm_ref(k): v for k, v in (erp.get("stock") or {}).items()}
    for pos, l in priced.items():
        m = norm_ref(l["material"])
        commit = (mail.get("delivery_commitments") or {}).get(norm_ref(l["keys"].get("delivery_key"))) \
            if l["keys"].get("delivery_key") else None
        if commit and norm_ref(commit.get("material")) == m and to_decimal(commit.get("max_total_pieces")) is not None \
                and demand[m] <= to_decimal(commit["max_total_pieces"]) and to_decimal(commit.get("weeks")) is not None:
            l["lead"] = int(to_decimal(commit["weeks"]))
            continue
        free = to_decimal((stock.get(m) or {}).get("free"))
        stock_weeks = to_decimal(l["erp"].get("lead_time_stock_weeks"))
        prod_weeks = to_decimal(l["erp"].get("lead_time_production_weeks"))
        chosen = stock_weeks if (free is not None and free >= demand[m]) else prod_weeks
        l["lead"] = int(chosen) if chosen is not None else None
        if l["lead"] is None:
            issues.append(f"{pos}: lead time unknown")

    # 6. answer
    blocked = [pos for pos in lines if (matched.get(pos) or {}).get("reason") == "only blocked matches"]
    decision = "no_bid" if blocked else "bid"
    positions = []
    for pos, l in priced.items():
        if l.get("lead") is None:
            omitted.append(pos)
            continue
        entry = {"position": pos, "material_number": l["material"], "quantity": l["pieces"],
                 "unit_price": float(l["unit_price"]), "lead_time_weeks": l["lead"],
                 "base_unit_price": float(l["base"])}
        for field, key in (("surcharge_per_unit", "surcharge_report"), ("packaging_per_unit", "packaging_report"),
                           ("rebate_total", "rebate_report")):
            if l.get(key) is not None:
                entry[field] = float(l[key])
        positions.append(entry)
        l["display"] = {k: de_number(Decimal(str(v))) for k, v in entry.items()
                        if k in ("unit_price", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total")}
    total = round_cents(sum((Decimal(e["quantity"]) * Decimal(str(e["unit_price"])) for e in positions), D0))
    answer = {"tender_reference": brief.get("tender_reference") or (tender.get("meta") or {}).get("reference") or "",
              "decision": decision, "currency": "EUR", "discount_percent": float(pct if decision == "bid" else D0),
              "positions": positions if decision == "bid" else [], "total_net": float(total) if decision == "bid" else 0.0}
    if decision == "no_bid":
        issues.append(f"no active material for {blocked}: no_bid")
    return {"answer": answer, "omitted": sorted(set(omitted)) if decision == "bid" else [],
            "total_display": de_number(total if decision == "bid" else D0), "order_value": str(order_value),
            "lines": [{k: (str(v) if isinstance(v, Decimal) else v) for k, v in l.items() if k != "erp"}
                      for l in lines.values()],
            "issues": issues}


@register
class BidCalculator(Agent):
    phase = Phase.COMPUTE

    async def run(self) -> None:
        names = ("brief", "tender", "quantities", "requirements", "materials", "erp", "discount", "mail")
        bid = compute({n: self.ctx.board.get(n) for n in names})
        await self.ctx.board.set("bid", bid)
        await self.ctx.board.set("answer", bid["answer"])
        self.log.info("bid: %s omitted=%s issues=%s", bid["answer"], bid["omitted"], bid["issues"])
# OWNER: (name)   ROLE: submitter   NEEDS: results["bid"], results["brief"]   WRITES: enters the bid on the tender portal, signs
"""Enters the computed bid in the tender portal's submission wizard and signs it with the TAN from the webmail.

The model drives the wizard (browser 0) from the brief's submission instructions and a table of the values to enter;
`fill_form` sets many fields per step. When the wizard asks for the signing TAN the model calls `get_signing_tan`,
which runs a short browse on the mail browser (3) to read the newest TAN mail. Runs even if earlier phases failed:
then every position without data is omitted ("partial submission"), the bid is still signed.
"""
import time

from pydantic import BaseModel, Field

from swarm import Agent, Phase, register
from swarm.blackboard import Evidence
