        if not conds:
            gap("erp", f"erp prices {mat}", f"price condition records of material {mat} with quantity scales")
        elif cond is None:
            gap("erp", f"erp prices {mat}", f"price condition of material {mat} valid on {brief.get('scenario_date')} "
