sys.path.insert(0, r"C:\Users\crubs\Desktop\tum_hackathon\ehl-finale-template")
from playwright.async_api import async_playwright  # noqa: E402

from swarm.guard import SCAN_JS  # noqa: E402

OUT = os.path.join(os.path.dirname(__file__), "probe_out.md")
DUMP_JS = r"""(words) => {
  const docs = [document];
  for (let i = 0; i < docs.length && i < 80; i++) {
    for (const f of docs[i].querySelectorAll('iframe')) { try { if (f.contentDocument) docs.push(f.contentDocument); } catch (e) {} }
    for (const el of docs[i].querySelectorAll('*')) { if (el.shadowRoot) docs.push(el.shadowRoot); }
  }
  const out = [];
  for (const d of docs) for (const el of d.querySelectorAll('*')) {
    const own = [...el.childNodes].filter(n => n.nodeType === 3).map(n => n.nodeValue).join(' ');
    if (words.some(w => own.toLowerCase().includes(w))) {
      let box = el; for (let k = 0; k < 4 && box.parentElement; k++) box = box.parentElement;
      const host = el.getRootNode().host;
      const s = getComputedStyle(box);
      out.push({word: own.trim().slice(0, 80), tag: el.tagName, in_shadow: !!host, host: host ? host.tagName : null,
                box: box.tagName + '#' + box.id + '.' + (box.className || ''), position: s.position, z: s.zIndex,
                role: box.getAttribute('role'), html: box.outerHTML.slice(0, 1500)});
    }
  }
  return out.slice(0, 6);
}"""


def access():
    raw = json.loads(os.environ["CHALLENGE_SITE_ACCESS"])
    return {s["siteId"]: s for s in (raw if isinstance(raw, list) else raw.get("access", raw))}


async def login(page, site):
    creds = site.get("credentials") or {}
    await page.goto(site["url"], wait_until="domcontentloaded")
    await page.wait_for_timeout(1500)
    for label in ("Alle akzeptieren", "Nur notwendige", "Akzeptieren"):
        b = page.get_by_role("button", name=label)
        if await b.count():
            await b.first.click()
            break
    pw = page.locator("input[type=password]")
    if await pw.count():
        user = page.locator("input:not([type=password]):not([type=hidden]):not([type=checkbox])").first
        await user.fill(creds.get("username", ""))
        await pw.first.fill(creds.get("password", ""))
        await pw.first.press("Enter")
        await page.wait_for_timeout(2500)


async def dump(page, title, words, f):
    scan = await page.evaluate(SCAN_JS)
    found = await page.evaluate(DUMP_JS, words)
    text = await page.evaluate("() => document.body.innerText.length")
    f.write(f"\n## {title}\n\nurl {page.url}; body text length {text}\n\nguard scan items:\n")
    for it in scan["items"]:
        f.write(f"- {it['kind']}: {it['text'][:160]!r} buttons {[b['label'] for b in it['buttons']]} fields {it['fields']}\n")
    for x in found:
        f.write(f"\nmatch {x['word']!r} tag {x['tag']} shadow {x['in_shadow']} host {x['host']} box {x['box']} "
                f"position {x['position']} z {x['z']} role {x['role']}\n```html\n{x['html']}\n```\n")


async def main():
    sites = access()
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        with open(OUT, "w", encoding="utf-8") as f:
            erp = next(s for k, s in sites.items() if "erp" in k)
            page = await b.new_page()
            await login(page, erp)
            await dump(page, "ERP after login", ["wartung", "nicht verfügbar", "erneut", "akzeptieren", "zugang"], f)
            for link in ("MM03", "MMBE", "VK13"):
                loc = page.get_by_text(link, exact=False)
                if await loc.count():
                    await loc.first.click()
                    await page.wait_for_timeout(2000)
                    await dump(page, f"ERP after clicking {link}", ["wartung", "nicht verfügbar", "erneut", "akzeptieren"], f)
                    await page.go_back()
                    await page.wait_for_timeout(1500)
            mail = next(s for k, s in sites.items() if "mail" in k)
            page = await b.new_page()
            await login(page, mail)
            await dump(page, "Mail after login", ["roboter", "schieb", "gesperrt", "entsperr", "wartung", "hinweis"], f)
        await b.close()
    print("written", OUT)


asyncio.run(main())

