    try:
        shown = [{k: item[k] for k in ("id", "kind", "text", "buttons", "fields")} for _, item in unknown]
        reply = await asyncio.wait_for(
            self.ctx.llm.ask_json(SYSTEM, json.dumps({"items": shown}, ensure_ascii=False)), CLASSIFY_TIMEOUT_S)
